import * as React from "react";
type Value = string | number | Date | boolean | null | undefined;
type DataTableColumn<T> = {
    id: string;
    /** The column's label, in its head and in the Columns menu. */
    header: React.ReactNode;
    /** What the cell shows; defaults to the accessor's value. */
    cell?: (row: T) => React.ReactNode;
    /** The value used to sort and filter. */
    accessor?: (row: T) => Value;
    sortable?: boolean;
    /** Whether the Columns menu can hide it (default true). */
    hideable?: boolean;
    /** Hidden until turned on in the Columns menu. */
    hidden?: boolean;
    align?: "start" | "end";
    className?: string;
};
type SortState = {
    id: string;
    desc: boolean;
} | null;
/** A sortable head label: a quiet button whose arrow shows the direction (both carets while unsorted). */
declare function DataTableColumnHeader({ title, sorted, onSort, className }: {
    title: React.ReactNode;
    sorted: false | "asc" | "desc";
    onSort?: () => void;
    className?: string;
}): React.JSX.Element;
/** The Columns button and its menu of checkboxes, one per column that can be hidden. */
declare function DataTableViewOptions({ columns, visible, onVisibleChange }: {
    columns: {
        id: string;
        header: React.ReactNode;
    }[];
    visible: Record<string, boolean>;
    onVisibleChange: (id: string, on: boolean) => void;
}): React.JSX.Element;
/** The row under the table: the selection count and rows per page at the left, the page and its buttons at the right. */
declare function DataTablePagination({ page, pageCount, onPageChange, pageSize, pageSizes, onPageSizeChange, selected, total, className }: {
    page: number;
    pageCount: number;
    onPageChange: (page: number) => void;
    pageSize?: number;
    pageSizes?: number[];
    onPageSizeChange?: (size: number) => void;
    selected?: number;
    total?: number;
    className?: string;
}): React.JSX.Element;
type DataTableProps<T> = {
    columns: DataTableColumn<T>[];
    data: T[];
    getRowId: (row: T) => string;
    /** A filter field over these columns' values (all filterable columns when omitted). */
    filter?: {
        placeholder?: string;
        columns?: string[];
    } | false;
    /** A checkbox column for choosing rows. */
    selectable?: boolean;
    selection?: string[];
    onSelectionChange?: (ids: string[]) => void;
    /** Hide the Columns menu. */
    hideViewOptions?: boolean;
    pageSize?: number;
    /** Offer these page sizes under the table. */
    pageSizes?: number[];
    defaultSort?: SortState;
    /** Shown in the body when nothing matches. */
    empty?: React.ReactNode;
    /** Actions at the toolbar's right, before the Columns menu. */
    toolbar?: React.ReactNode;
    /** What a row is called in labels ("mailbox"). */
    rowName?: string;
    className?: string;
};
declare function DataTable<T>({ columns, data, getRowId, filter, selectable, selection: selectionProp, onSelectionChange, hideViewOptions, pageSize: pageSizeProp, pageSizes, defaultSort, empty, toolbar, rowName, className }: DataTableProps<T>): React.JSX.Element;
export { DataTable, DataTableColumnHeader, DataTablePagination, DataTableViewOptions };
export type { DataTableColumn, DataTableProps, SortState };

